"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function toJSONWithout(model, keys) {
  const data = { ...model.get() };
  for (const key of keys) delete data[key];
  return data;
}

class User extends Model {
  toJSON() {
    return toJSONWithout(this, ["id", "updatedAt", "createdAt"]);
  }
}

class Article extends Model {
  toJSON() {
    return toJSONWithout(this, ["id", "userId"]);
  }
}

class Comment extends Model {
  toJSON() {
    return toJSONWithout(this, ["articleId", "userId"]);
  }
}

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
User.hasMany(Comment, { foreignKey: "userId" });
